#include "forms.h"
#include "socket.h"
static void append(char *s,const char *v){copy(s+strlen(s),v);}
static int min(int a,int b){return a<b?a:b;}
int FormsAdd(FormProject *p,int type,int x,int y){if(p->count==FORM_CONTROLS||type<1||type>7)return S_LIMIT;int i=p->count++;Control *c=&p->controls[i];memset(c,0,sizeof(*c));c->type=type;c->x=x;c->y=y;c->w=type==CONTROL_LABEL?210:140;c->h=type==CONTROL_LIST?86:26;c->interval=100;const char *names[]={"","Label","Button","TextBox","CheckBox","ListBox","Timer","Menu"};copy(c->name,names[type]);char number_text[12];number((u32)p->count,number_text);append(c->name,number_text);for(int candidate=p->count;;candidate++){int used=BasicEqual(c->name,p->name);for(int j=0;j<i;j++)if(BasicEqual(c->name,p->controls[j].name))used=1;if(!used)break;copy(c->name,names[type]);number((u32)candidate+1,number_text);append(c->name,number_text);}copy(c->text,names[type]);if(type==CONTROL_LIST)copy(c->text,"One;Two;Three");return i;}
void FormsBlank(FormProject *p){memset(p,0,sizeof(*p));copy(p->name,"Form1");copy(p->title,"Form1");p->width=480;p->height=280;}
void FormsDefault(FormProject *p){FormsBlank(p);copy(p->title,"我的第一个 SINO 程序");int i=FormsAdd(p,CONTROL_LABEL,24,25);copy(p->controls[i].name,"Label1");copy(p->controls[i].text,"Hello SINO");i=FormsAdd(p,CONTROL_BUTTON,24,88);copy(p->controls[i].name,"Button1");copy(p->controls[i].text,"Click me");}
static int safe_name(const char *s){if(!s[0])return 0;for(u32 i=0;s[i];i++)if(i>=30||!((s[i]>='A'&&s[i]<='Z')||(s[i]>='a'&&s[i]<='z')||s[i]=='_'||(i&&s[i]>='0'&&s[i]<='9')))return 0;return 1;}
static int integer(const char *s){u32 n=0;if(!*s)return -1;while(*s){if(*s<'0'||*s>'9'||n>10000)return -1;n=n*10+(u32)(*s++-'0');}return (int)n;}
static int fields(const char **text,char *line,char **out){int n=0;while(**text&&**text!='\n'&&**text!='\r'){if(n==255)return -1;line[n++]=*(*text)++;}line[n]=0;while(**text=='\n'||**text=='\r')(*text)++;int count=1;out[0]=line;for(int i=0;line[i];i++)if(line[i]=='|'){if(count==10)return -1;line[i]=0;out[count++]=line+i+1;}return count;}
int FormsLoad(FormProject *p,const char *text){FormProject next;memset(&next,0,sizeof(next));char line[256],*part[10];int n=fields(&text,line,part);if((n!=4&&n!=5)||!streq(part[0],"SFORM1")||strlen(part[1])>63||(n==5&&!safe_name(part[4])))return S_INVALID;copy(next.name,n==5?part[4]:"Form1");copy(next.title,part[1]);next.width=integer(part[2]);next.height=integer(part[3]);if(next.width<200||next.width>600||next.height<100||next.height>400)return S_INVALID;while(*text){n=fields(&text,line,part);if(n!=10||next.count==FORM_CONTROLS)return S_INVALID;Control *c=&next.controls[next.count++];c->type=integer(part[0]);if(c->type<1||c->type>7||!safe_name(part[1])||strlen(part[2])>63)return S_INVALID;copy(c->name,part[1]);copy(c->text,part[2]);c->x=integer(part[3]);c->y=integer(part[4]);c->w=integer(part[5]);c->h=integer(part[6]);c->value=integer(part[7]);c->interval=integer(part[8]);if(!streq(part[9],"end")||c->x<0||c->y<0||c->w<20||c->h<16||c->x+c->w>next.width||c->y+c->h>next.height||c->interval<1||c->interval>1000)return S_INVALID;for(int j=0;j<next.count-1;j++)if(BasicEqual(next.controls[j].name,c->name))return S_INVALID;}*p=next;return 0;}
static int add(char *out,u32 cap,const char *s){u32 n=strlen(out),bytes=strlen(s);if(n+bytes>=cap)return 0;copy(out+n,s);return 1;}
int FormsSave(const FormProject *p,char *out,u32 cap){if(cap<32)return S_LIMIT;out[0]=0;char number_text[12];if(!add(out,cap,"SFORM1|")||!add(out,cap,p->title))return S_LIMIT;number((u32)p->width,number_text);if(!add(out,cap,"|")||!add(out,cap,number_text))return S_LIMIT;number((u32)p->height,number_text);if(!add(out,cap,"|")||!add(out,cap,number_text)||!add(out,cap,"|")||!add(out,cap,p->name)||!add(out,cap,"\n"))return S_LIMIT;
 for(int i=0;i<p->count;i++){const Control *c=&p->controls[i];number((u32)c->type,number_text);if(!add(out,cap,number_text)||!add(out,cap,"|")||!add(out,cap,c->name)||!add(out,cap,"|")||!add(out,cap,c->text))return S_LIMIT;const int values[]={c->x,c->y,c->w,c->h,c->value,c->interval};for(int j=0;j<6;j++){number((u32)values[j],number_text);if(!add(out,cap,"|")||!add(out,cap,number_text))return S_LIMIT;}if(!add(out,cap,"|end\n"))return S_LIMIT;}return (int)strlen(out);}
void FormsRender(const FormProject *p,UiScene *s,int ox,int oy,int design){
 ui_fill(s,ox,oy,p->width,p->height,0xc0c0c0);
 for(int i=0;i<p->count;i++){const Control *c=&p->controls[i];int x=ox+c->x,y=oy+c->y;
 if(c->type==CONTROL_LABEL)ui_mono_clip(s,x,y+3,c->w,c->text,0x202020);
 else if(c->type==CONTROL_BUTTON||c->type==CONTROL_MENU){ui_panel(s,x,y,c->w,c->h,0xc0c0c0,0);ui_mono_clip(s,x+7,y+5,c->w-14,c->text,0x202020);}
 else if(c->type==CONTROL_CHECK){ui_panel(s,x,y+4,16,16,0xffffff,1);if(c->value)ui_mono(s,x+3,y+4,"x",0x202020);ui_mono_clip(s,x+23,y+5,c->w-23,c->text,0x202020);}
 else if(c->type==CONTROL_TEXT){ui_panel(s,x,y,c->w,c->h,0xffffff,1);ui_mono_clip(s,x+4,y+5,c->w-8,c->text,0x202020);}
 else if(c->type==CONTROL_LIST){ui_panel(s,x,y,c->w,c->h,0xffffff,1);const char *start=c->text;int row=0;while(*start&&row<(c->h-4)/20){char line[64];int n=0;while(*start&&*start!=';')line[n++]=*start++;line[n]=0;if(*start==';')start++;if(c->value==row)ui_fill(s,x+2,y+2+row*20,c->w-4,20,0xb5c9ea);ui_mono_clip(s,x+4,y+5+row*20,c->w-8,line,0x202020);row++;}}
 else if(design){ui_panel(s,x,y,32,26,0xc0c0c0,0);ui_mono(s,x+4,y+5,"(t)",0x202020);}
 }
}
static int find(const FormProject *p,const char *property,const char **field){char name[32];u32 i=0;while(property[i]&&property[i]!='.'){if(i>=31)return -1;name[i]=property[i];i++;}if(property[i]!='.')return -1;name[i]=0;*field=property+i+1;for(int n=0;n<p->count;n++)if(BasicEqual(name,p->controls[n].name))return n;return -1;}
int FormsGet(const FormProject *p,const char *property,BasicValue *out){const char *field;int i=find(p,property,&field);if(i<0)return S_NOTFOUND;const Control *c=&p->controls[i];memset(out,0,sizeof(*out));if(BasicEqual(field,"Caption")||BasicEqual(field,"Text"))BasicString(out,c->text);else if(BasicEqual(field,"Value"))out->number=c->value;else if(BasicEqual(field,"Left"))out->number=c->x;else if(BasicEqual(field,"Top"))out->number=c->y;else if(BasicEqual(field,"Width"))out->number=c->w;else if(BasicEqual(field,"Height"))out->number=c->h;else if(BasicEqual(field,"Interval"))out->number=c->interval;else return S_NOTFOUND;return 0;}
int FormsSet(FormProject *p,const char *property,const BasicValue *v){const char *field;int i=find(p,property,&field);if(i<0)return S_NOTFOUND;Control *c=&p->controls[i];if(BasicEqual(field,"Caption")||BasicEqual(field,"Text")){char text[128];BasicText(v,text);if(strlen(text)>63)return S_LIMIT;for(u32 j=0;text[j];j++)if(text[j]=='|'||text[j]=='\r'||text[j]=='\n')return S_INVALID;copy(c->text,text);return 0;}if(v->string)return S_INVALID;int n=v->number;if(BasicEqual(field,"Value")){if(n<0||n>31)return S_INVALID;c->value=n;return 0;}if(BasicEqual(field,"Interval")){if(n<1||n>1000)return S_INVALID;c->interval=n;return 0;}Control next=*c;if(BasicEqual(field,"Left"))next.x=n;else if(BasicEqual(field,"Top"))next.y=n;else if(BasicEqual(field,"Width"))next.w=n;else if(BasicEqual(field,"Height"))next.h=n;else return S_INVALID;if(next.x<0||next.y<0||next.w<20||next.h<16||next.x+next.w>p->width||next.y+next.h>p->height)return S_INVALID;*c=next;return 0;}
static void event_name(const Control *c,const char *type,char *out){copy(out,c->name);append(out,"_");append(out,type);}
int FormsInput(FormProject *p,UiEvent *e,int ox,int oy,int *focus,char *event){event[0]=0;if(e->type==MSG_CLICK){for(int i=p->count-1;i>=0;i--){Control *c=&p->controls[i];if(ui_hit(e,ox+c->x,oy+c->y,c->w,c->h)){*focus=i;if(c->type==CONTROL_CHECK)c->value=!c->value;if(c->type==CONTROL_LIST)c->value=min((e->y-oy-c->y)/20,31);if(c->type!=CONTROL_TEXT&&c->type!=CONTROL_TIMER)event_name(c,"Click",event);return 1;}}*focus=-1;}if((e->type==MSG_KEY||e->type==MSG_TEXT)&&*focus>=0){Control *c=&p->controls[*focus];if(c->type!=CONTROL_TEXT)return 0;u32 n=strlen(c->text);if(e->type==MSG_TEXT){char encoded[4];int bytes=text_encode((u32)e->key,encoded);if(n+(u32)bytes>63)return 0;memcpy(c->text+n,encoded,(u32)bytes);c->text[n+bytes]=0;}else if(e->key==8&&n){n--;while(n&&((u8)c->text[n]&0xc0)==0x80)n--;c->text[n]=0;}else if(e->key==1)c->text[0]=0;else if(e->key>=32&&e->key<127&&n<63){c->text[n]=(char)e->key;c->text[n+1]=0;}else return 0;event_name(c,"Change",event);return 1;}return 0;}
int FormsTimer(FormProject *p,char *event){u32 now=Tick();for(int i=0;i<p->count;i++){Control *c=&p->controls[i];if(c->type==CONTROL_TIMER&&now-c->last_tick>=(u32)c->interval){c->last_tick=now;event_name(c,"Timer",event);return 1;}}return 0;}
